package org.spiderclient.spiderbridge.bridge;

import java.util.Locale;

/**
 * A snapshot of the agent's published endpoint file.
 *
 * <p>The secret is generated by the agent for a single run and is read from a
 * file only the same operating-system user can read. It is never compiled into
 * this mod and never logged.
 */
public record Endpoint(int schema, int protocol, int port, String secret, String agentVersion, int agentPid) {
    public Endpoint {
        if (schema != Protocol.ENDPOINT_SCHEMA) {
            throw new IllegalArgumentException("unsupported endpoint schema " + schema);
        }
        if (port < 1 || port > 65535) {
            throw new IllegalArgumentException("endpoint port is out of range");
        }
        if (secret == null || secret.length() != Protocol.SECRET_HEX_CHARS) {
            throw new IllegalArgumentException("endpoint credential has the wrong length");
        }
        if (!secret.chars().allMatch(c -> (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
            throw new IllegalArgumentException("endpoint credential is not hexadecimal");
        }
        if (agentVersion == null || agentVersion.isBlank() || agentVersion.length() > 64) {
            throw new IllegalArgumentException("endpoint agent version is invalid");
        }
        if (agentPid <= 0) {
            throw new IllegalArgumentException("endpoint agent pid is invalid");
        }
    }

    @Override
    public String toString() {
        return "Endpoint[protocol=" + protocol + ", port=" + port + ", agent=" + agentVersion
                + ", pid=" + agentPid + ", secret=<redacted>]";
    }

    /** A short, non-secret summary for diagnostics. */
    public String describe() {
        return String.format(Locale.ROOT, "protocol %d on 127.0.0.1:%d (agent %s, pid %d)",
                protocol, port, agentVersion, agentPid);
    }
}
